import datetime
from robot.libraries.BuiltIn import BuiltIn


def log_info_to_console(msg=None, log_hierarchy=1):
    """
    Print INFO message to robot log and console.
    Sample output:
    [2022-02-02 14:56:17]        Level 2

    :param msg: str, message to print to console
    :param log_hierarchy: str, int, determine how deep should be indent,
    :return: None
    """
    msg = LoggerUtils.generate_msg(msg, log_hierarchy=log_hierarchy, add_timestamp=True, add_new_line=False,
                                   add_carriage_return=True)
    BuiltIn().log(message=msg, level='INFO', console=True)


def log_warn_to_console(msg=None, log_hierarchy=1):
    """
    Print WARNING message to robot log and console.
    Sample output:
    [2022-02-02 14:56:17][WARN]      Something went wong

    :param msg: str, message to print to console
    :param log_hierarchy: str, int, determine how deep should be indent,
    :return: None
    """
    msg = LoggerUtils.generate_msg(msg, log_hierarchy=log_hierarchy, add_timestamp=True, add_new_line=False,
                                   add_carriage_return=True, prefix='WARN')
    msg = LoggerUtils.add_warning_markers_to_msg(msg)
    BuiltIn().log(message=msg, level='WARN')


def log_banner_to_console(msg=None):
    """
    Print banner to robot log and console.
    Sample output:
    [2022-02-02 14:56:17]*********************************************************
    [2022-02-02 14:56:17]*
    [2022-02-02 14:56:17]*    Very Important thing
    [2022-02-02 14:56:17]*
    [2022-02-02 14:56:17]*********************************************************

    :param msg: str,list - message to print to console. If list is provided, each element will be printed in new line.
    :return: None
    """
    msg = LoggerUtils.generate_banner(msg)
    BuiltIn().log(message=msg, level='INFO', console=True)


class LoggerUtils(object):
    """
    Class contains utils for building message log.
    """
    BASE_SIZE = 52
    INDENT_MULTIPLIER = 4

    class TerminalColors(object):
        HEADER = '\033[95m'
        OKBLUE = '\033[34m'
        OKCYAN = '\033[36m'
        OKGREEN = '\033[32m'
        WARNING = '\033[33m'
        FAIL = '\033[31m'
        ENDC = '\033[0m'
        BOLD = '\033[1m'
        UNDERLINE = '\033[4m'

    @classmethod
    def generate_msg(cls, msg, log_hierarchy=1, add_timestamp=True, add_new_line=True, add_carriage_return=True, prefix=''):
        """
        Print formatted logs on the console.

        :param msg: str,
        :param log_hierarchy: int, determine how deep should be indent,
        :param add_timestamp: bool.
        :param add_new_line: bool, Add new line sign at te end of msg
        :param add_carriage_return: bool, Add carriage return sign at te begin of msg
        :param prefix: prefix msg - it will be added between timestamp and message
        :return: None
        """
        prefix_msg = '' if prefix == '' else '[{}]'.format(prefix)
        indent = ' ' * (cls.INDENT_MULTIPLIER * int(log_hierarchy) - len(prefix_msg)) if log_hierarchy else ''
        full_msg = ''
        if add_timestamp:
            full_msg = cls.get_formatted_timestamp()

        full_msg = "{}{}{}{}".format(full_msg, prefix_msg, indent, msg)
        full_msg = "\r{}".format(full_msg) if add_carriage_return else full_msg
        full_msg = "{}\n".format(full_msg) if add_new_line else full_msg

        return full_msg

    @classmethod
    def generate_banner(cls, msg):
        line_length = '*' * 57
        form_timestamp = cls.get_formatted_timestamp()
        if not isinstance(msg, list):
            msg = [msg]
        msg = [f"{form_timestamp}*    {_msg}\n" for _msg in msg]
        msg = ''.join(msg)
        banner = '\r{time}{len}\n{time}*\n{msg}{time}*\n{time}{len}'.format(
            time=form_timestamp, len=line_length, msg=msg)

        return banner

    @staticmethod
    def get_formatted_timestamp():
        timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        return "[{}]".format(timestamp)

    @staticmethod
    def add_warning_markers_to_msg(msg):
        return LoggerUtils.TerminalColors.WARNING + msg + LoggerUtils.TerminalColors.ENDC


